import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Resort {
  id: string;
  name: string;
  location: string;
  category: 'Sun' | 'Sea' | 'Snow' | 'International';
  description: string;
  imageUrl: string;
}

export interface PlannerResult {
  destinationType: string;
  recommendation: string;
  suggestedActivities: string[];
}

import { GoogleGenAI, Type } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

export const getHolidayRecommendation = async (userPreference: string): Promise<string> => {
  if (!API_KEY) return "AI services are currently unavailable. Please contact us directly!";

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Based on this dream holiday description: "${userPreference}", provide a 3-sentence luxury vacation recommendation that highlights the importance of "time" and "effortless experiences". Focus on quality and the "Dream Vacation Club" brand voice.`,
      config: {
        temperature: 0.7,
        topP: 0.9,
      }
    });

    return response.text || "We've imagined a beautiful stay for you. Let's make it a reality.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error generating your dream. Please try again.";
  }
};

