    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleAudio = () => {
    if (!audioRef.current) {
      audioRef.current = new Audio('https://www.soundjay.com/nature/ocean-waves-1.mp3');
      audioRef.current.loop = true;
    }

    if (isAudioPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch(e => console.log("Audio blocked: user interaction required."));
    }
    setIsAudioPlaying(!isAudioPlaying);
  };

  return (
    <section id="home" className="relative h-screen flex items-center justify-center overflow-hidden bg-slate-900">
      {/* Parallax & Ken Burns Background */}
      <div 
        className="absolute inset-0 z-0"
        style={{ 
          transform: `translateY(${scrollY * 0.4}px)`,
          transition: 'transform 0.1s ease-out'
