      </div>

      {/* Overlays */}
      <div className="absolute inset-0 z-[1] bg-gradient-to-b from-black/60 via-black/20 to-transparent"></div>

      {/* Content */}
      <div 
        className="relative z-10 text-center px-4 max-w-4xl"
        style={{ 
          transform: `translateY(${-scrollY * 0.1}px)`,
          transition: 'transform 0.1s ease-out'
        }}
      >
        <div className="mb-8 inline-flex items-center gap-3 bg-white/10 backdrop-blur-md px-6 py-2 rounded-full border border-white/20 animate-[fadeIn_1s_ease-out]">
          <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse"></span>
          <span className="text-white text-xs font-bold uppercase tracking-widest">Exclusive Membership</span>
        </div>

        <h1 className="text-5xl md:text-8xl text-white font-bold mb-6 leading-[1.1] drop-shadow-2xl">
