          >
            <i className="fas fa-video mr-2"></i> Visionize Your Dream
          </button>

          <button 
            onClick={toggleAudio}
            className={`flex items-center gap-4 px-8 py-5 rounded-full border-2 text-lg font-bold transition-all hover:scale-105 active:scale-95 backdrop-blur-sm ${isAudioPlaying ? 'bg-white/20 border-white text-white shadow-lg' : 'bg-transparent border-white text-white hover:bg-white/10'}`}
          >
            <div className="flex items-end gap-0.5 h-4 w-6">
              {[1, 2, 3, 4, 5].map(i => (
                <div 
                  key={i} 
                  className={`bg-current w-1 rounded-t-sm transition-all duration-300 ${isAudioPlaying ? 'animate-[soundwave_1s_ease-in-out_infinite]' : 'h-1'}`}
