        @keyframes kenburns {
          0% { transform: scale(1.1) translate(0, 0); }
          50% { transform: scale(1.2) translate(-2%, -1%); }
          100% { transform: scale(1.1) translate(0, 0); }
        }
        @keyframes soundwave {
          0%, 100% { height: 4px; }
          50% { height: 16px; }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}} />
    </section>
  );
};

