                    <span>Generate My Recommendation</span>
                  </>
                )}
              </button>
            </div>
          </div>

          <div className={`transition-all duration-700 sticky top-24 ${recommendation ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
